  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 2 · Shopping</h2><p>Сегодня — поход в магазин: как назвать всё по-английски и как заплатить.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'flashcards', $blk${"title": "Повторяем слова урока. Нажми на карточку — услышишь слово и увидишь перевод", "cards": [{"text": "cashier", "translation": "кассир", "audio": "", "audio_tts": {"text": "cashier.", "voice": "en_GB-alba"}}, {"text": "shopping list", "translation": "список покупок", "audio": "", "audio_tts": {"text": "shopping list.", "voice": "en_GB-alba"}}, {"text": "shopping trolley", "translation": "тележка для покупок", "audio": "", "audio_tts": {"text": "shopping trolley.", "voice": "en_GB-alba"}}, {"text": "shopping basket", "translation": "корзина для покупок", "audio": "", "audio_tts": {"text": "shopping basket.", "voice": "en_GB-alba"}}, {"text": "shopping bag", "translation": "сумка для покупок", "audio": "", "audio_tts": {"text": "shopping bag.", "voice": "en_GB-alba"}}, {"text": "special offer", "translation": "акция, скидка", "audio": "", "audio_tts": {"text": "special offer.", "voice": "en_GB-alba"}}, {"text": "card", "translation": "банковская карта", "audio": "", "audio_tts": {"text": "card.", "voice": "en_GB-alba"}}, {"text": "cash", "translation": "наличные", "audio": "", "audio_tts": {"text": "cash.", "voice": "en_GB-alba"}}, {"text": "change", "translation": "сдача", "audio": "", "audio_tts": {"text": "change.", "voice": "en_GB-alba"}}, {"text": "price", "translation": "цена", "audio": "", "audio_tts": {"text": "price.", "voice": "en_GB-alba"}}, {"text": "receipt", "translation": "чек", "audio": "", "audio_tts": {"text": "receipt.", "voice": "en_GB-alba"}}, {"text": "queue", "translation": "очередь", "audio": "", "audio_tts": {"text": "queue.", "voice": "en_GB-alba"}}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини слово с объяснением", "pairs": [{"left": "cashier", "right": "the person who takes your money in a shop"}, {"left": "shopping list", "right": "the paper with the things you need to buy"}, {"left": "shopping trolley", "right": "you push it around the supermarket"}, {"left": "shopping basket", "right": "you carry it in your hand"}, {"left": "change", "right": "the money you get back after you pay"}, {"left": "receipt", "right": "the paper that shows how much you paid"}, {"left": "queue", "right": "the line of people waiting to pay"}, {"left": "special offer", "right": "a lower price for a short time"}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай предложение и выбери правильное слово", "questions": [{"q": "My dad ___ the shopping home in a big shopping bag.", "type": "single", "correct": [0], "options": [{"text": "carries"}, {"text": "checks"}]}, {"q": "Would you like to pay in ___?", "type": "single", "correct": [0], "options": [{"text": "cash"}, {"text": "card"}]}, {"q": "When I pay for the shopping, I make sure I get the correct ___.", "type": "single", "correct": [1], "options": [{"text": "price"}, {"text": "change"}]}, {"q": "Check how much everything costs after you shop on the ___.", "type": "single", "correct": [1], "options": [{"text": "price"}, {"text": "receipt"}]}, {"q": "Let's stand in this ___. It's short.", "type": "single", "correct": [1], "options": [{"text": "change"}, {"text": "queue"}]}, {"q": "I always get a shopping ___ because it’s easier when you buy a lot of things.", "type": "single", "correct": [0], "options": [{"text": "trolley"}, {"text": "bag"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор в магазине и перетащи слова в пропуски", "mode": "drag", "text": "Paul: Have you got the shopping list, Katy?\nKaty: Yes. Here you are. Can I put these biscuits in the shopping __trolley__, please? They're a __special__ offer.\nMum: How much are they?\nPaul: Let's check the __price__. They're 70p for six. Is that cheap?\nMum: Yes. I think we've got everything. Let's pay __for__ the shopping there. The __queue__ is short."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'sort', $blk${"title": "Распредели слова по группам", "groups": [{"name": "💳 этим платят", "items": [{"text": "card"}, {"text": "cash"}]}, {"name": "🛒 сюда кладут покупки", "items": [{"text": "bag"}, {"text": "basket"}, {"text": "trolley"}]}, {"name": "🧾 здесь смотрят цену", "items": [{"text": "receipt"}, {"text": "special offer"}]}]}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Расскажи вслух и запиши ответ", "needs_review": true, "html": "<p>Расскажи, как ты ходишь в магазин: что берёшь с собой, чем платишь, во что кладёшь покупки.</p>", "sample": "", "sample_tts": {"text": "I always write a shopping list.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_star.webp\" alt=\"\" style=\"height:200px\"></p><p>Отлично! Теперь ты знаешь, как всё назвать в магазине.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'f342c5ca-ce88-40dc-b97a-79032ef7a76f' and title = 'Homework 2';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('f342c5ca-ce88-40dc-b97a-79032ef7a76f', 'Homework 2', 1, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 1, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_girl_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 2 · Сравнение</h2><p>Сегодня сравниваем: кто быстрее, что интереснее и что самое-самое.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши сравнительную форму прилагательного из скобок", "mode": "type", "text": "Cats are __smaller__ (small) than elephants.\nMary's schoolbag is __bigger__ (big) than my schoolbag. It takes more books.\nDad says chess is __more interesting__ (interesting) than video games, but I think it's boring.\nChores are __worse__ (bad) than homework. I don't like them.\nThis test is __easier__ (easy) than the last test. I know all the answers."}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Составь предложения в превосходной степени", "items": [{"words": ["Mark", "is", "the", "most", "intelligent", "student", "in", "my", "class."], "sentence": "Mark is the most intelligent student in my class.", "prompt": "Mark / intelligent student / in my class"}, {"words": ["Ice", "Age", "5", "is", "the", "best", "film", "at", "the", "cinema", "this", "week."], "sentence": "Ice Age 5 is the best film at the cinema this week.", "prompt": "Ice Age 5 / good film / at the cinema this week"}, {"words": ["Basketball", "is", "the", "most", "exciting", "sport", "I", "know."], "sentence": "Basketball is the most exciting sport I know.", "prompt": "Basketball / exciting sport / I know"}, {"words": ["My", "friend", "Jack", "is", "the", "funniest", "boy", "in", "our", "school."], "sentence": "My friend Jack is the funniest boy in our school.", "prompt": "My friend Jack / funny boy / in our school"}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай, что Джордж говорит на своём дне рождения, и выбери правильную форму", "questions": [{"q": "This is the ___ party in my life.", "type": "single", "correct": [1], "options": [{"text": "nicer"}, {"text": "nicest"}]}, {"q": "The jokes and games are ___ than last year.", "type": "single", "correct": [1], "options": [{"text": "funniest"}, {"text": "funnier"}]}, {"q": "It is the most ___ cake in the world.", "type": "single", "correct": [1], "options": [{"text": "biggest"}, {"text": "amazing"}]}, {"q": "She always answers the ___ difficult questions!", "type": "single", "correct": [1], "options": [{"text": "more"}, {"text": "most"}]}, {"q": "Mum, thanks for everything. You are the ___.", "type": "single", "correct": [1], "options": [{"text": "better"}, {"text": "best"}]}], "material": "<p><b>George:</b> «Guys, thanks for the presents. This is the <sup>1</sup>… party in my life. The jokes and games are <sup>2</sup>… than last year – well done, Harry! And the cake is great, Poppy. It is the most <sup>3</sup>… cake in the world. As usual Emma is the winner of all the games. She always answers the <sup>4</sup>… difficult questions! And Mum, thanks for everything. You are the <sup>5</sup>….»</p>"}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор Поппи и Эммы и впиши сравнительную или превосходную форму", "mode": "type", "text": "Poppy: Hi, Emma. Can you help me with my French homework? You're __better__ (good) than me. I can't do Exercise 4. It's __more difficult__ (difficult) than the other exercises. It's __longer__ (long) than the other exercises too. It's got thirty questions! It's __the most boring__ (boring) exercise in this book!\nEmma: Don't worry. Let's see. That's funny ...\nPoppy: What?\nEmma: Well, I don't know these words! You are looking at page 59. Our homework is on page 29.\nPoppy: Good! I'm not __the worst__ (bad) student in our French class!"}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши правдивые предложения о себе", "needs_review": true, "html": "<p>Напиши пять предложений про себя — в сравнительной или превосходной степени. Выбери одно прилагательное из пары.</p><ol><li>I / runner / than my best friend — <b>fast / slow</b></li><li>Monday / day / in my week — <b>good / bad</b></li><li>video games / than books — <b>interesting / boring</b></li><li>my mum / than me — <b>tall / short</b></li><li>my street / than my school’s street — <b>quiet / noisy</b></li></ol>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_trophy.webp\" alt=\"\" style=\"height:200px\"></p><p>Молодец! Сравнивать теперь получается и в словах, и в предложениях.</p>"}$blk$::jsonb, 6);
end $$;

