  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_highfive.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 2 · Магазины и too / enough</h2><p>Сегодня — названия магазинов и как сказать «слишком» и «достаточно».</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'flashcards', $blk${"title": "Повторяем названия магазинов. Нажми на карточку — услышишь слово и увидишь перевод", "cards": [{"text": "baker's", "translation": "булочная", "audio": "", "audio_tts": {"text": "baker's.", "voice": "en_GB-alba"}}, {"text": "bookshop", "translation": "книжный магазин", "audio": "", "audio_tts": {"text": "bookshop.", "voice": "en_GB-alba"}}, {"text": "chemist's", "translation": "аптека", "audio": "", "audio_tts": {"text": "chemist's.", "voice": "en_GB-alba"}}, {"text": "clothes shop", "translation": "магазин одежды", "audio": "", "audio_tts": {"text": "clothes shop.", "voice": "en_GB-alba"}}, {"text": "department store", "translation": "универмаг", "audio": "", "audio_tts": {"text": "department store.", "voice": "en_GB-alba"}}, {"text": "greengrocer's", "translation": "овощной магазин", "audio": "", "audio_tts": {"text": "greengrocer's.", "voice": "en_GB-alba"}}, {"text": "newsagent's", "translation": "газетный киоск", "audio": "", "audio_tts": {"text": "newsagent's.", "voice": "en_GB-alba"}}, {"text": "shoe shop", "translation": "обувной магазин", "audio": "", "audio_tts": {"text": "shoe shop.", "voice": "en_GB-alba"}}, {"text": "sports shop", "translation": "спортивный магазин", "audio": "", "audio_tts": {"text": "sports shop.", "voice": "en_GB-alba"}}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай и выбери, в каком магазине это купят", "questions": [{"q": "Where can you buy bread and cakes?", "type": "single", "correct": [0], "options": [{"text": "a baker's"}, {"text": "a bookshop"}, {"text": "a chemist's"}]}, {"q": "Where can you buy apples and potatoes?", "type": "single", "correct": [1], "options": [{"text": "a shoe shop"}, {"text": "a greengrocer's"}, {"text": "a sports shop"}]}, {"q": "Where can you buy medicine?", "type": "single", "correct": [0], "options": [{"text": "a chemist's"}, {"text": "a newsagent's"}, {"text": "a clothes shop"}]}, {"q": "Where can you buy a magazine?", "type": "single", "correct": [1], "options": [{"text": "a bookshop"}, {"text": "a newsagent's"}, {"text": "a department store"}]}, {"q": "Where can you buy trainers and a football?", "type": "single", "correct": [1], "options": [{"text": "a baker's"}, {"text": "a sports shop"}, {"text": "a chemist's"}]}, {"q": "Where can you buy clothes, food and toys in one building?", "type": "single", "correct": [0], "options": [{"text": "a department store"}, {"text": "a shoe shop"}, {"text": "a bookshop"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши too или enough и прилагательное из рамки: big · clean · expensive · old · small", "mode": "type", "text": "You can't wear Dad's T-shirt. It's __too big__.\nI haven't got lots of money, so I can't buy these trainers. They are __too expensive__.\nThese glasses aren't __clean enough__. You need to wash them again.\nTina isn't __old enough__ to see this film. It's for 15-year-olds and she is twelve.\nOh no! This pizza is __too small__. It has six pieces and there are twenty people here."}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини начало и конец предложения", "pairs": [{"left": "These black shoes are as", "right": "nice as those brown shoes."}, {"left": "The apples aren't", "right": "as expensive as the oranges."}, {"left": "Honey shampoo isn't as cheap", "right": "as lemon shampoo."}, {"left": "Is your school bag as heavy", "right": "as my bag?"}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Составь предложения из слов", "items": [{"words": ["This", "shampoo", "is", "too", "expensive", "for", "me."], "sentence": "This shampoo is too expensive for me.", "prompt": "слишком дорогой"}, {"words": ["These", "oranges", "are", "sweet", "enough", "for", "me."], "sentence": "These oranges are sweet enough for me.", "prompt": "достаточно сладкие"}, {"words": ["This", "book", "isn't", "interesting", "enough", "for", "me."], "sentence": "This book isn't interesting enough for me.", "prompt": "недостаточно интересная"}, {"words": ["The", "shopping", "bags", "aren't", "too", "heavy", "for", "her."], "sentence": "The shopping bags aren't too heavy for her.", "prompt": "не слишком тяжёлые"}]}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор в магазине и впиши too, enough или as", "mode": "type", "text": "Rob: What's on the list?\nMillie: Four small apples. Are these green apples small __enough__?\nRob: No. They're __too__ big. What about those red apples?\nMillie: They aren't __as__ big as the green apples. Let's buy four red apples.\nRob: OK. What's next on the list?\nMillie: Six lemon or chocolate cupcakes. I think lemon cupcakes aren't __as__ tasty as chocolate cupcakes.\nRob: I think chocolate cupcakes are __too__ sweet!\nMillie: I think lemon cupcakes aren't sweet __enough__!\nRob: Let's get three lemon cupcakes and three chocolate cupcakes.\nMillie: Good idea!"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_medal.webp\" alt=\"\" style=\"height:200px\"></p><p>Супер — теперь ты можешь сказать, что слишком дорого, а чего не хватает.</p>"}$blk$::jsonb, 7);
end $$;

do $$
