  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини начало и конец фразы", "pairs": [{"left": "Can I", "right": "help you?"}, {"left": "No, thanks. I'm", "right": "just looking."}, {"left": "Do you", "right": "have this in a small?"}, {"left": "Sorry,", "right": "we don't."}, {"left": "Can I try", "right": "it on?"}, {"left": "Yes, of course. The changing rooms", "right": "are over there."}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай реплику продавца или покупателя и выбери ответ", "questions": [{"q": "A: Good morning. Can I help you?", "type": "single", "correct": [2], "options": [{"text": "Thanks, but I don't want it."}, {"text": "Yes, we can."}, {"text": "No, thanks. I'm just looking."}]}, {"q": "A: Excuse me, this top is too small.", "type": "single", "correct": [1], "options": [{"text": "They're a size 10."}, {"text": "What size are you?"}, {"text": "No, they're big."}]}, {"q": "A: Do you have this top in a different colour?", "type": "single", "correct": [0], "options": [{"text": "What colour are you looking for?"}, {"text": "It's a size 10."}, {"text": "Would you like a smaller top?"}]}, {"q": "A: What size is that coat?", "type": "single", "correct": [2], "options": [{"text": "It's expensive."}, {"text": "I think it's purple."}, {"text": "Medium."}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор Теда с продавцом и впиши пропущенное слово", "mode": "type", "text": "Assistant: Can I help you?\nTed: Yes, __please__. I'm looking for a T-shirt.\nAssistant: What __size__ are you?\nTed: I'm a small, I think. Do you __have__ this T-shirt in black?\nAssistant: Yes, we __do__.\nTed: Cool. Can I __try__ it on?\nAssistant: Yes, of course. The changing __rooms__ are over there."}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай два разговора в магазине и впиши пропущенные слова", "mode": "type", "text": "1\nAssistant: Can I help you?\nPeter: Yes, please. I'm __looking for__ orange trainers.\nAssistant: What __size__ are you?\nPeter: Thirty-nine. Do you __have them__ in green?\nAssistant: Sorry, we __don't__.\n2\nTracy: Excuse me. Do you __have__ this grey hoodie in a small?\nAssistant: Yes, we __do__.\nTracy: Great. Can I __try it__ on?\nAssistant: Yes, __of course__. The changing __rooms__ are over there.\nTracy: Thank you."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Разыграй разговор в магазине и запиши ответ", "needs_review": true, "html": "<p>Ты хочешь купить зелёную куртку. Ты носишь размер 8, а на куртке размер 10. Поговори с продавцом: поздоровайся, скажи, что ищешь, спроси про свой размер и про примерочную.</p>", "sample": "", "sample_tts": {"text": "Excuse me. Do you have this jacket in a size eight?", "voice": "en_GB-alba"}}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_thumb.webp\" alt=\"\" style=\"height:200px\"></p><p>Отлично! Теперь в магазине одежды ты не растеряешься.</p>"}$blk$::jsonb, 6);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'f342c5ca-ce88-40dc-b97a-79032ef7a76f' and title = 'Homework 5';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('f342c5ca-ce88-40dc-b97a-79032ef7a76f', 'Homework 5', 4, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 4, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_girl_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 2 · Reading</h2><p>Сегодня читаем блог Вики про кафе, где на завтрак — хлопья.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<h3>Cereal Cafés <span style=\"color:#888\">by Vicky</span></h3><p><b>What's the most amazing breakfast food in the world? For me, it's cereal! It's tastier than eggs and it's more interesting than bread.</b></p><p>Now you can have breakfast at a cereal café! It's called ‘Rainbow’ and it is in Oxford in the UK. It has 123 different cereals and thirty different types of milk! Inside, the café looks like a bedroom because there are chairs and beds to sit on. You can enjoy British and American cereals. Kids usually drink hot chocolate, but their parents prefer tea or coffee. Its opening hours are 8 a.m. to 8 p.m., so you can have breakfast all day. You can also book kids' parties here!</p><p>There's also a cereal café, ‘Fantastico’, inside a big department store in Boston in the USA. This café has twenty-two different cereals. OK, that isn't as amazing as the cereal café in Oxford. But there is a surprise – they serve cereal with ice cream. It isn't breakfast – it's dessert! I'd like chocolate cereal with vanilla milk, please!</p><p><i>Your comments: Which café would you like to visit? What would you like to try? Write to me.</i></p>"}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай блог ещё раз и выбери правильный ответ", "questions": [{"q": "When can you go to a cereal café in Oxford?", "type": "single", "correct": [0], "options": [{"text": "all day"}, {"text": "only in the morning"}, {"text": "only in the afternoon"}]}, {"q": "The ___ UK cereal café is in Oxford.", "type": "single", "correct": [0], "options": [{"text": "‘Rainbow’"}, {"text": "‘Fantastico’"}]}, {"q": "There are ___ different types of milk at the café in Oxford.", "type": "single", "correct": [1], "options": [{"text": "123"}, {"text": "30"}]}, {"q": "The cereal café in Oxford is like a ___.", "type": "single", "correct": [0], "options": [{"text": "bedroom"}, {"text": "kitchen"}]}, {"q": "It's open ___ hours a day.", "type": "single", "correct": [1], "options": [{"text": "eleven"}, {"text": "twelve"}]}, {"q": "The cereal café in Boston is in a ___.", "type": "single", "correct": [0], "options": [{"text": "shop"}, {"text": "restaurant"}]}, {"q": "They serve ice cream in the café in ___.", "type": "single", "correct": [0], "options": [{"text": "Boston"}, {"text": "Oxford"}]}], "material": "<h3>Cereal Cafés <span style=\"color:#888\">by Vicky</span></h3><p><b>What's the most amazing breakfast food in the world? For me, it's cereal! It's tastier than eggs and it's more interesting than bread.</b></p><p>Now you can have breakfast at a cereal café! It's called ‘Rainbow’ and it is in Oxford in the UK. It has 123 different cereals and thirty different types of milk! Inside, the café looks like a bedroom because there are chairs and beds to sit on. You can enjoy British and American cereals. Kids usually drink hot chocolate, but their parents prefer tea or coffee. Its opening hours are 8 a.m. to 8 p.m., so you can have breakfast all day. You can also book kids' parties here!</p><p>There's also a cereal café, ‘Fantastico’, inside a big department store in Boston in the USA. This café has twenty-two different cereals. OK, that isn't as amazing as the cereal café in Oxford. But there is a surprise – they serve cereal with ice cream. It isn't breakfast – it's dessert! I'd like chocolate cereal with vanilla milk, please!</p><p><i>Your comments: Which café would you like to visit? What would you like to try? Write to me.</i></p>"}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай блог ещё раз и впиши по одному слову в каждый пропуск", "mode": "type", "text": "Cereal is tastier than __eggs__.\nBread isn't as __interesting__ as cereal.\nYou can __drink__ hot chocolate, tea or coffee in the café.\nPeople organise kids' __parties__ at the cereal café.\nThere are __twenty-two__ types of cereals at the café in Boston.\nVicky wants __vanilla__ milk on her cereal.", "material": "<h3>Cereal Cafés <span style=\"color:#888\">by Vicky</span></h3><p><b>What's the most amazing breakfast food in the world? For me, it's cereal! It's tastier than eggs and it's more interesting than bread.</b></p><p>Now you can have breakfast at a cereal café! It's called ‘Rainbow’ and it is in Oxford in the UK. It has 123 different cereals and thirty different types of milk! Inside, the café looks like a bedroom because there are chairs and beds to sit on. You can enjoy British and American cereals. Kids usually drink hot chocolate, but their parents prefer tea or coffee. Its opening hours are 8 a.m. to 8 p.m., so you can have breakfast all day. You can also book kids' parties here!</p><p>There's also a cereal café, ‘Fantastico’, inside a big department store in Boston in the USA. This café has twenty-two different cereals. OK, that isn't as amazing as the cereal café in Oxford. But there is a surprise – they serve cereal with ice cream. It isn't breakfast – it's dessert! I'd like chocolate cereal with vanilla milk, please!</p><p><i>Your comments: Which café would you like to visit? What would you like to try? Write to me.</i></p>"}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай блог ещё раз и выбери ответ", "questions": [{"q": "What is Vicky's favourite breakfast food?", "type": "single", "correct": [0], "options": [{"text": "cereal"}, {"text": "eggs"}]}, {"q": "Which menu is from the cereal café in Oxford?", "type": "single", "correct": [1], "options": [{"text": "a menu with 30 cereals"}, {"text": "a menu with 123 cereals"}]}, {"q": "What do kids usually drink at the cereal café in Oxford?", "type": "single", "correct": [1], "options": [{"text": "tea"}, {"text": "hot chocolate"}]}, {"q": "What's the surprise at the café in Boston?", "type": "single", "correct": [0], "options": [{"text": "ice cream"}, {"text": "a birthday cake"}]}, {"q": "What would Vicky like?", "type": "single", "correct": [0], "options": [{"text": "chocolate cereal with vanilla milk"}, {"text": "ice cream in a cone"}]}], "material": "<h3>Cereal Cafés <span style=\"color:#888\">by Vicky</span></h3><p><b>What's the most amazing breakfast food in the world? For me, it's cereal! It's tastier than eggs and it's more interesting than bread.</b></p><p>Now you can have breakfast at a cereal café! It's called ‘Rainbow’ and it is in Oxford in the UK. It has 123 different cereals and thirty different types of milk! Inside, the café looks like a bedroom because there are chairs and beds to sit on. You can enjoy British and American cereals. Kids usually drink hot chocolate, but their parents prefer tea or coffee. Its opening hours are 8 a.m. to 8 p.m., so you can have breakfast all day. You can also book kids' parties here!</p><p>There's also a cereal café, ‘Fantastico’, inside a big department store in Boston in the USA. This café has twenty-two different cereals. OK, that isn't as amazing as the cereal café in Oxford. But there is a surprise – they serve cereal with ice cream. It isn't breakfast – it's dessert! I'd like chocolate cereal with vanilla milk, please!</p><p><i>Your comments: Which café would you like to visit? What would you like to try? Write to me.</i></p>"}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Ответь на вопросы Вики", "needs_review": true, "html": "<p>Напиши два предложения: в какое кафе ты бы сходил и что бы попробовал.</p><p>Начни так: <i>I would like to visit the cereal café in … I would like to try …</i></p>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_popper.webp\" alt=\"\" style=\"height:200px\"></p><p>Здорово! Текст прочитан, а завтрак теперь звучит вкусно.</p>"}$blk$::jsonb, 6);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'f342c5ca-ce88-40dc-b97a-79032ef7a76f' and title = 'Homework 6';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('f342c5ca-ce88-40dc-b97a-79032ef7a76f', 'Homework 6', 5, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 5, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_highfive.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 2 · Listening and Writing</h2><p>Сегодня слушаем, что хотят купить ребята, и пишем письмо другу.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "LISTENING 🎧 Послушай запись и соедини предмет с ценой", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A5.mp3", "skill": "listening", "pairs": [{"left": "headphones", "right": "£30"}, {"left": "a torch", "right": "£9"}, {"left": "a mobile phone", "right": "£200"}, {"left": "a camera", "right": "£70"}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "LISTENING 🎧 Послушай запись ещё раз и соедини, кому что нравится", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A5.mp3", "skill": "listening", "pairs": [{"left": "Martha likes", "right": "the headphones."}, {"left": "Andy likes", "right": "the blue torch."}, {"left": "Sally likes", "right": "the mobile phone."}, {"left": "Fred likes", "right": "the camera."}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "LISTENING 🎧 Послушай запись ещё раз и выбери: верно, неверно или не сказано", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A5.mp3", "skill": "listening", "questions": [{"q": "Martha wants a new mobile phone.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "Martha's favourite colour is red.", "type": "single", "correct": [2], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "Andy has lots of money.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "Andy wants a torch for camping.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "Sally's old phone has a camera.", "type": "single", "correct": [2], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "Sally likes the most expensive thing in the shop.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "Fred has a blue camera.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "Fred can buy a camera with money from his grandparents.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай письмо Терри и впиши слова: finally · first · more · opinion", "mode": "drag", "text": "Hi Tony,\nThere are different backpacks at the department store in the city centre. There are three special offers. The ‘Whizz’ backpack isn't too bad, but I don't think it's the best choice. It isn't big enough. The ‘Super’ backpack is bigger than the ‘Whizz’, but in my __opinion__ the ‘Power’ backpack is the best. __First__ of all, it's big enough for books and a tablet. What's __more__, it has a key. __Finally__, it's the cheapest backpack.\nBye for now,\nTerry"}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Посмотри на цены трёх футболок и впиши пропущенное слово", "mode": "type", "text": "The __blue__ T-shirt is the most expensive.\nThe __green__ T-shirt is bigger than the blue T-shirt and the pink T-shirt.\nThe __pink__ T-shirt has words on it.\nThe __pink__ T-shirt is the cheapest.", "material": "<p><b>Три футболки в магазине:</b></p><ul><li>синяя — £22</li><li>зелёная — £18</li><li>розовая с надписью HELLO SUN — £10</li></ul>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши другу письмо о том, какая футболка лучше", "needs_review": true, "html": "<p><b>Три футболки в магазине:</b></p><ul><li>синяя — £22</li><li>зелёная — £18</li><li>розовая с надписью HELLO SUN — £10</li></ul><p>Напиши Юле письмо: какая футболка, по-твоему, лучше и почему. Используй <b>in my opinion</b>, <b>first of all</b>, <b>what’s more</b>, <b>finally</b>.</p><p>Начни так: <i>Hi Julia, There are different T-shirts in the department store in the city centre. …</i></p>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_certificate.webp\" alt=\"\" style=\"height:200px\"></p><p>Отлично! Ты услышал цены и написал настоящее письмо с доводами.</p>"}$blk$::jsonb, 7);
end $$;

do $$
