    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 2 · Check yourself!</h2><p>Повторяем весь юнит перед тестом.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'exact_input', $blk${"title": "Напиши слово по-английски", "items": [{"prompt": "корзина для покупок (b…)", "accept": ["basket", "Basket", "shopping basket"]}, {"prompt": "сдача (c…)", "accept": ["change", "Change"]}, {"prompt": "тележка для покупок (t…)", "accept": ["trolley", "Trolley", "shopping trolley"]}, {"prompt": "наличные (c…)", "accept": ["cash", "Cash"]}, {"prompt": "чек (r…)", "accept": ["receipt", "Receipt"]}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай предложение и выбери правильное слово", "questions": [{"q": "I'd like to pay ___ card.", "type": "single", "correct": [0], "options": [{"text": "by"}, {"text": "in"}]}, {"q": "Let's get some bread at the ___.", "type": "single", "correct": [1], "options": [{"text": "bookshop"}, {"text": "baker's"}]}, {"q": "Dad doesn't want to stand in the ___.", "type": "single", "correct": [1], "options": [{"text": "offer"}, {"text": "queue"}]}, {"q": "They've got new trainers at the ___.", "type": "single", "correct": [0], "options": [{"text": "sports shop"}, {"text": "chemist's"}]}, {"q": "This ___ has good fruit.", "type": "single", "correct": [1], "options": [{"text": "newsagent's"}, {"text": "greengrocer's"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини начало и конец предложения", "pairs": [{"left": "Dad is taller", "right": "than Mum."}, {"left": "Oranges are sweeter", "right": "than apples."}, {"left": "This T-shirt is the", "right": "cheapest T-shirt in the shop."}, {"left": "French is more", "right": "difficult than English."}, {"left": "Dave is the most", "right": "intelligent student in the class."}, {"left": "We are", "right": "the happiest kids in the world!"}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор и впиши too, enough, as или not", "mode": "type", "text": "A: My laptop is __too__ slow to play video games. I need a new one.\nB: Look at this laptop. I think it's fast __enough__ for games.\nA: It isn't __as__ small as that one, but I like it.\nB: The size is a problem. Can you put it in your bag? I think it's __too__ big.\nA: Yes, you're right. But it is __not__ as expensive as that laptop. I can buy a new bag.\nB: That's true. Look. This laptop bag is as cheap __as__ a schoolbag! It's a special offer."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Собери разговор в магазине: соедини реплику с ответом", "pairs": [{"left": "Can I", "right": "help you?"}, {"left": "Yes, please. I'm", "right": "looking for a jacket."}, {"left": "What size", "right": "are you?"}, {"left": "I'm a medium. Do", "right": "you have this jacket in blue?"}, {"left": "Can I", "right": "try it on?"}, {"left": "Yes, of course. The changing", "right": "rooms are over there."}]}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Расскажи вслух и запиши ответ", "needs_review": true, "html": "<p>Расскажи про свой любимый магазин: как он называется по-английски, что там покупают и почему он тебе нравится. Скажи три-четыре предложения.</p>", "sample": "", "sample_tts": {"text": "My favourite shop is the bookshop near my house.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_trophy.webp\" alt=\"\" style=\"height:200px\"></p><p>Юнит пройден! Теперь можно браться за тест.</p>"}$blk$::jsonb, 7);
end $$;
